"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type KeyboardEvent, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a star rating. Pass `value` to control it, or `defaultValue` to let it hold its own score. Zero means no score yet. */
export type StarRatingProps = Omit<ComponentPropsWithoutRef<"div">, "onChange" | "defaultValue" | "children"> & {
  /** The accessible name of the group, for example "Rate the delivery". */
  label?: string;
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  /** One word per star, lowest first. The number of words sets the number of stars. */
  words?: readonly string[];
  disabled?: boolean;
};

type Direction = 1 | -1;

const DEFAULT_WORDS = ["Poor", "Fair", "Okay", "Good", "Great"] as const;
// Damping 49 is 2 × √600, rounded up: the chosen star settles from its pop without a wobble.
const POP_SPRING: Transition = { type: "spring", stiffness: 600, damping: 49, mass: 1 };
const ROLL_SPRING: Transition = { type: "spring", stiffness: 520, damping: 46, mass: 1 };
const FADE: Transition = { duration: 0.15 };
const POP_FROM = 1.3;

// The direction travels through `custom`, because a leaving word keeps the
// props of its last render and would exit the old way.
const ROLL = {
  enter: (dir: Direction) => ({ y: `${dir * 100}%`, opacity: 0 }),
  shown: { y: 0, opacity: 1 },
  leave: (dir: Direction) => ({ y: `${-dir * 100}%`, opacity: 0 }),
};
const CROSSFADE = { enter: { opacity: 0 }, shown: { opacity: 1 }, leave: { opacity: 0 } };

/**
 * Pick a score in stars. The stars fill up to the pointer, the chosen star
 * pops, and a word for the score rolls in beneath. It is a radio group, so
 * the arrow keys move the choice.
 */
export function StarRating({
  label = "Rating",
  value,
  defaultValue = 0,
  onValueChange,
  words = DEFAULT_WORDS,
  disabled = false,
  className,
  onKeyDown,
  onPointerLeave,
  ...divProps
}: StarRatingProps) {
  const [ownValue, setOwnValue] = useState(defaultValue);
  const [hovered, setHovered] = useState(0);
  const [picks, setPicks] = useState(0);
  const starsRef = useRef<(HTMLButtonElement | null)[]>([]);
  const reduceMotion = useReducedMotion();
  const count = words.length;
  const rating = Math.max(0, Math.min(count, value ?? ownValue));
  const shown = hovered || rating;

  // A higher score rolls its word up from below; a lower one comes down from above.
  const [roll, setRoll] = useState<{ shown: number; dir: Direction }>({ shown, dir: 1 });
  if (roll.shown !== shown) setRoll({ shown, dir: shown > roll.shown ? 1 : -1 });

  const select = (next: number) => {
    if (value === undefined) setOwnValue(next);
    setPicks(picks + 1);
    if (next !== rating) onValueChange?.(next);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event);
    if (event.defaultPrevented || disabled) return;
    let next: number;
    if (event.key === "ArrowRight" || event.key === "ArrowDown") next = rating >= count ? 1 : rating + 1;
    else if (event.key === "ArrowLeft" || event.key === "ArrowUp") next = rating <= 1 ? count : rating - 1;
    else if (event.key === "Home") next = 1;
    else if (event.key === "End") next = count;
    else return;
    event.preventDefault();
    select(next);
    starsRef.current[next - 1]?.focus();
  };

  return (
    <div
      {...divProps}
      role="radiogroup"
      aria-label={label}
      aria-disabled={disabled || undefined}
      onKeyDown={handleKeyDown}
      onPointerLeave={(event) => {
        onPointerLeave?.(event);
        setHovered(0);
      }}
      className={cn("inline-flex flex-col items-center gap-1", className)}
    >
      <div className="flex">
        {words.map((word, index) => {
          const score = index + 1;
          const chosen = rating === score;
          const lit = score <= shown;
          return (
            <button
              key={word}
              ref={(star) => {
                starsRef.current[index] = star;
              }}
              type="button"
              role="radio"
              aria-checked={chosen}
              aria-label={`${score} ${score === 1 ? "star" : "stars"}, ${word}`}
              // One tab stop for the group: the chosen star, or the first when none is chosen.
              tabIndex={(rating || 1) === score ? 0 : -1}
              disabled={disabled}
              onClick={() => select(score)}
              // A touch has no hover; lighting stars under a finger would stick after the tap.
              onPointerEnter={(event) => {
                if (event.pointerType === "mouse") setHovered(score);
              }}
              className={cn(
                "grid size-11 cursor-pointer touch-manipulation place-items-center rounded-full outline-none",
                "motion-safe:transition motion-safe:duration-150 active:scale-95",
                "focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50",
              )}
            >
              <motion.span
                // A new key restarts the pop, so choosing the same star again still answers.
                key={chosen ? `pick-${picks}` : "rest"}
                initial={chosen && picks > 0 && !reduceMotion ? { scale: POP_FROM } : false}
                animate={{ scale: 1 }}
                transition={POP_SPRING}
                className="flex"
              >
                <svg
                  viewBox="0 0 24 24"
                  aria-hidden="true"
                  // An empty star is an outline and a lit one is solid, so the score never rests on colour.
                  fill={lit ? "currentColor" : "none"}
                  stroke="currentColor"
                  strokeWidth="1.5"
                  strokeLinejoin="round"
                  className={cn(
                    "size-7 motion-safe:transition-colors motion-safe:duration-150",
                    lit ? "text-foreground" : "text-muted-foreground",
                  )}
                >
                  <path d="m12 2.75 2.86 5.8 6.39.93-4.63 4.5 1.1 6.37L12 17.34l-5.72 3.01 1.1-6.37-4.63-4.5 6.39-.93L12 2.75Z" />
                </svg>
              </motion.span>
            </button>
          );
        })}
      </div>
      {/* Hidden from screen readers: each star already reads its word. */}
      <div aria-hidden="true" className="relative h-5 w-full overflow-hidden text-center text-sm font-medium text-foreground">
        <AnimatePresence mode="popLayout" initial={false} custom={roll.dir}>
          <motion.span
            key={shown}
            custom={roll.dir}
            variants={reduceMotion ? CROSSFADE : ROLL}
            initial="enter"
            animate="shown"
            exit="leave"
            transition={reduceMotion ? FADE : ROLL_SPRING}
            className="block w-full"
          >
            {shown > 0 ? words[shown - 1] : ""}
          </motion.span>
        </AnimatePresence>
      </div>
    </div>
  );
}
